import re
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import EmployeePayrollRecord
from .serializers import PayrollSerializer

ALLOWED_ORIGIN_REGEX = re.compile(r'^https://([a-z0-9-]+\.)?company\.com$')

class EmployeePayrollDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def dispatch(self, request, *args, **kwargs):
        response = super().dispatch(request, *args, **kwargs)
        origin = request.headers.get('Origin')
        if origin and ALLOWED_ORIGIN_REGEX.match(origin):
            response['Access-Control-Allow-Origin'] = origin
            response['Access-Control-Allow-Credentials'] = 'true'
        return response

    def get(self, request, employee_id):
        # Enforce that employee can only access their own record or requires HR permission
        if str(request.user.employee_profile.employee_id) != str(employee_id) and not request.user.has_perm('hr.view_all_payroll'):
            return Response({'error': 'Access denied'}, status=status.HTTP_403_FORBIDDEN)

        try:
            record = EmployeePayrollRecord.objects.get(employee_id=employee_id)
        except EmployeePayrollRecord.DoesNotExist:
            return Response({'error': 'Record not found'}, status=status.HTTP_404_NOT_FOUND)

        return Response(PayrollSerializer(record).data)
